$path='C:\Users\pc\Desktop\TheBlackLilyBloomsinHerEyes\chinese-patch\source\data\scenario\zh-CN\story\chapter2s2.ks'
$m=@{
554='_　我做了一个梦。梦见自己在森林里被漆黑泥浆般的人偶追赶。[l][r]';555='_　遮蔽夜空的树木被蔓延的火星点燃，熊熊燃烧；从灼烧肌肤的火焰间隙传来的怒吼与悲鸣，不断刺痛耳膜。[l][r]';556='_　祈求饶恕的声音，寻求帮助的声音。[l][r]';557='_　我甩开身边所有怨恨与叫喊，强行拖动破烂的双腿，向森林深处不停逃窜。[l][r]';558='_　树枝刺入脚趾，我把因剧痛几乎漏出的[ruby text="おえつ"]呜咽硬生生压回喉咙。[p]';559='_　好害怕。好痛苦。好疼。好想哭。[l][r]';560='_　我将所有哀叹忍在胸中，拼命奔跑、不断奔跑。可黑暗中伸出的手，仍不允许我逃走。[l][r]';561='_　双腿绊住，身体[ruby text="くずお"]颓然倒下。坚硬的手臂撞碎肩膀，眼前逼近[ruby text="せんせき"]穿石的铁枪。[l][r]';562='_　人群――泥人偶发出声音。背对被钉起的十字架和[ruby text="く"]燃烧的业火，历史排斥了少女们。[l][r]';563='_　杀死女巫。消灭女巫。[l][r]';564='_　世界――属于人类。[p]';581='第二天上学时，我完全无法集中精神听课。[p]';582='原因显而易见。在还没消化昨天的经历――魔法这个全新世界时，[p]';583='我的脑袋并不聪明到还能继续塞进学习知识。[p]';584='除此之外，还有另一个让我无法消除疲劳的原因――[p]';588='「……壹十，怎么了？感觉你今天一直都很困。」[p]';590='邀请我一起回家的朋友，似乎担心心不在焉的我，开口问道。[p]';592='「啊……昨晚做了不好的梦，没睡好。」[p]';594='「喂喂，你今天还要打工吧？这种状态没问题吗？」[p]';596='「还没到会直接倒下的程度，没事。」[p]';598='――我做了梦。一个至今仍记得清清楚楚的可怕噩梦。[p]';599='虽然没有证据断定是铃造成的，但也不能说完全无关。[p]';600='如果这是得到铃后的副作用，那已经与其说是魔法，不如说更像诅咒。[p]';601='要是今晚还做那个噩梦，或许该找例前辈商量一下。[p]';603='「对了，关于今天布置的作业范围――」[p]';607='我暂且把身体状况放到一边，和朋友聊着无关紧要的话，走出鞋柜。[p]';608='穿上皮鞋，慢悠悠地走下坡道――[p]';611='走近校门时，我发现本校学生正喧闹地聚在那里。[p]';613='「……怎么了？」[p]';615='校门旁边――以某一点为中心，形成了一片圆形空地。[p]';616='我越过远处围观学生的头顶观察，那里――[p]';619='一个熟悉的红发美女正坐在鲜红敞篷车的车门上。[p]';621='「哇，好酷的车，好漂亮的美女。是在拍模特写真之类的吗？」[p]';623='「……也许吧。」[p]';625='与校园格格不入的豪华汽车，以及完全不顾场合的华丽装束。[p]';626='加上无可比拟的美貌，她从好坏两方面都格外引人注目。[p]';627='目的十有八九是我。希望她在学校另有熟人，未免太过乐观。[p]';628='我正想着能否不被发现、装作陌生人蒙混过去时，[p]';630='却冒失地与那锐利目光对上了。[p]';632='「哦！你来了，壹十。」[p]';635='她从车门起身迈出一步，人群仿佛摩西的奇迹般在连接我与世界小姐的直线上分开。[p]';636='那暴烈的化身踏着铿锵鞋声走近。[p]';637='我满心想逃，本能却[ruby text="すく"]退缩了，双脚一步也无法后退。[p]';642='「哟，看起来精神不错。没想到你在这么聪明的学校上学啊。」[p]';644='「谢谢……“没想到”就多余了。」[p]';646='她像初次相遇时一样，用力搂住并抓紧我的肩膀。[p]';647='果然力气惊人，骨头都在悲鸣。[p]';650='「听例前辈说了，你从出生起就一直住在京都。」[p]';651='「我正好想观光，今天陪我约会一天吧。」[p]';653='「呃……抱歉。虽然很高兴你邀请我，但我今天要打工……」[p]';655='「放心，老板和例前辈都同意了。你今天的工作就是陪我玩。」[p]';657='「这样也可以吗……？」[p]';660='「只要我说可以，黑乌鸦也能变白。」[p]';662='这是蛮不讲理。而且即便得到老板和例前辈许可，却不问当事人意见，她就是暴君。[p]';665='「就是这么回事。不好意思，这家伙借我一会儿。」[p]';667='「好、好的……请便。」[p]';669='我从一开始就不可能拥有否定的权利，[p]';670='在朋友目瞪口呆的目送下，我被她扛进了世界小姐的车。[p]';687='「清水寺……」[p]';690='「怎么，摆出一副没见过世面的样子？」[p]';692='「没什么……像这样买票登上舞台，我还是小学时的事了。」[p]';694='「真意外。还是说对当地人而言太熟悉，反而不常来？」[p]';696='「因人而异吧。我只是没兴趣，班上也有同学几乎每周都去逛寺庙。」[p]';698='说起清水寺，它是京都数一数二的名胜，但我上次像这样混在游客中参观，究竟是多少年前了？[p]';699='瞳也喜欢历史建筑，但和她约会时我们优先去第一次拜访的地方，[p]';700='所以一直没机会来这种熟悉的寺庙。[p]';703='「我啊，死的时候想从清水寺舞台跳下去死。」[p]';705='「听说那时候舞台下面是树木和松软泥土，所以没想象中那么容易死。」[p]';707='「哦？那现在呢？」[p]';709='「现在……会死吧。下面不是树和土，而是铺好的混凝土地面。」[p]';711='虽说这么回答，但这个人就算从清水寺舞台跳下去，似乎也不会死。[p]';712='还是我擅自把她估计得太高了？[p]';713='不过，我甚至想象出这样一幅画面：即使从上段挥下土产店买来的木刀，碎掉的也会是木刀而非她的脑袋。[p]';714='我从世界小姐身上感受到某种深不可测的东西。[p]';716='「话说，这把木刀今天都得一直拿着吗？」[p]';718='「我不是说了是防身用吗？毕竟昨晚一口气有三名铃之持有者被猎杀了。」[p]';720='仪式的参加者――铃之持有者被打倒了。[p]';721='这是前往清水寺途中，世界小姐在车里告诉我的仪式进展。[p]';722='听说截至昨晚，已有三名铃之持有者被某人打倒，铃的魔力也被夺走。[p]';724='「昨天例前辈提到的“异常”员工七々扇战华，以及小清水家下一任家主候选小清水纱月。」[p]';725='「还有和我一样的自由魔术师，塔堂雷。」[p]';727='三人之中，塔堂雷是被我打倒的对手，另外两人则是我第一次听说的讨伐对象。[p]';728='也就是说，除了我之外，昨晚还有铃之持有者打倒了两名魔术师――人数是我的两倍。[p]';730='「……世界小姐特意来学校，难道也有确认我是否平安的意思吗？」[p]';732='如果是这样，她之前的蛮横或许也是害羞的掩饰，我对她的看法会立刻改变。[p]';735='「不是？我来找你，只是为了找个免费的向导。」[p]';737='「啊，这样啊……」[p]';739='果然，世界小姐就是世界小姐。表里都坦率直白，毫不掩饰。[p]';741='「那个，世界小姐。铃的魔法白天不会生效，对吧？」[p]';744='「嗯。太阳升起时我就完全感觉不到铃的魔力了，应该和例前辈的推测一样。」[p]';746='「那么，现在这个时间没必要带防身武器吧……」[p]';749='「就算没有铃的魔法，普通魔法也能用吧？」[p]';751='原来如此。我只能使用铃的魔法，所以没想到这一点；普通魔术师当然也能使用其他魔法。[p]';753='「……魔法这种东西，木刀能对付吗？」[p]';756='「有气势的话总能想办法吧。」[p]';758='「诶……」[p]';760='这所谓的应对策略未免太随便了。[p]';761='至少我所知道的召唤魔法，强大到即使让我拿着手枪，也看不见获胜的可能，更别说刀了。[p]';762='那是超越人类认知的存在。[p]';763='……我还是相信，单靠暴力抢夺无法夺走铃的魔力。[p]';765='「……袭击那三个人的家伙，就是举行仪式的魔术师吗？」[p]';767='严格来说是两人，但我隐瞒自己打倒其中一人的事实发问。[p]';769='「不知道，还不能断言。不过至少可以确定，是连我和例前辈都不认识的――」[p]';770='「野生魔术师。说不定和你一样，是昨天才成为魔术师的家伙。」[p]';772='「那个……刚成为魔术师的外行，能打赢有经验的人吗？」[p]';775='「普通魔法战斗的话，基本没有胜算。不过，这个仪式是从外部严格按照[ruby text="ルール"]规则制定的召唤战。」[p]';776='「正因为没有被自成一派的魔法知识束缚，像你这样的外行或许更容易战斗。」[p]';778='「从外部……？」[p]';781='「比如，我要是在这里――」[p]';784='「――就说“[ruby text="アウェイクン"]启动”吧。」[p]';787='那句话――那句听过的咒语，让我全身毛孔竖起，反射性地摆出架势。[p]';788='『[ruby text="アウェイクン"]启动』。召唤战――世界反转的开始信号。[p]';789='然而，';791='可是这一次，清水寺舞台上交谈的人群并没有发生任何变化。[p]';794='「放心，我说过白天不会生效吧。」[p]';796='「啊……对，是这样。」[p]';799='「不过，我也不知道它是不是真的不会生效。」[p]';800='「毕竟用这句咒语展开结界、在领域内使用召唤魔法――都不是我的魔法。」[p]';802='铃中[ruby text="こ"]蕴含的替代性魔法力量――召唤魔法。[p]';803='我记得瞳也曾这样向我解释过。[p]';806='「真是的，越调查越觉得有人启动了不得了的麻烦仪式。」[p]';807='「表面上迎合京都风土，采用东方魔术形式来伪装并提高魔力运用效率。」[p]';808='「可领域内部――战斗场地中被迫使用的召唤魔法，却彻头彻尾是西方魔术。」[p]';809='「它很清楚我们这些生于东方的魔术师不习惯使用西方魔术。」[p]';811='「原来魔法也分东西方啊。」[p]';813='我本来就不了解魔法这一概念，更难想象细分出的体系。[p]';816='「我也不太懂细节，但说成计量单位不同，应该比较好理解。」[p]';817='「你知道公制和英制的区别吗？」[p]';819='「一英码是多少米来着？」[p]';821='「是0.9144米。只是打个比方，如果东方魔术用米来构筑魔法，西方魔术就是用码来构筑。」[p]';822='「所以习惯米制的人不熟悉码制，理解起来就会很辛苦。」[p]';824='我大概理解了。[p]';825='也就是说，像我这种既不懂米也不懂码的外行，反而比只懂米制的人更容易适应。[p]';827='「可以理解成语言的差异吗？」[p]';830='「差不多，但魔法方言没那么天差地别。只是称呼不同，本质部分是相同的。」[p]';831='「无论用公制还是英制测量，清水寺舞台的面积都不会改变吧？」[p]';833='正面约18米，侧面约10米。换算成码，数值会更复杂一些吧。[p]';834='无论如何，只要两个人面对面――只要作为战斗场地――这里都足够宽敞。[p]'
}
$lines=[System.Collections.Generic.List[string]](Get-Content $path -Encoding UTF8); foreach($n in $m.Keys){$lines[$n-1]=$m[$n]}; [IO.File]::WriteAllLines($path,$lines,[Text.UTF8Encoding]::new($false))
